function validate(input) {
  const [arr, size] = input;
  if (!Array.isArray(arr)) return 'arr must be an array.';
  if (JSON.stringify(arr).length > 100000) return 'arr is too large: keep its JSON text within 10^5 characters.';
  if (!Number.isInteger(size) || size < 1 || size > arr.length + 1) return 'size must be an integer from 1 to arr.length + 1.';
  return null;
}

