function chunk(arr, size) {
  // Deal the elements one by one into the current piece, closing it once it is full.
  const result = [];
  let current = [];
  for (const item of arr) {
    current.push(item);
    if (current.length === size) {
      result.push(current);
      current = [];
    }
  }
  if (current.length > 0) result.push(current);
  return result;
}

