function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const value = () => {
    const roll = rand();
    if (roll < 0.6) return Math.floor(rand() * 41) - 20;
    if (roll < 0.7) return pick(['a', 'xy', '', 'hello']);
    if (roll < 0.8) return pick([null, true, false]);
    if (roll < 0.9) return { id: Math.floor(rand() * 10) };
    return [Math.floor(rand() * 10), [Math.floor(rand() * 10)]];
  };
  const length = small ? Math.floor(rand() * 9) : 1500 + Math.floor(rand() * 501);
  const arr = Array.from({ length }, value);
  // Mostly small pieces, sometimes one that is as long as the array or one longer.
  const roll = rand();
  const pieceSize = roll < 0.15 ? length + 1 : roll < 0.3 ? Math.max(1, length) : 1 + Math.floor(rand() * Math.min(length + 1, small ? 4 : 60));
  return [arr, pieceSize];
}
